    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Start with the residual after placing the item
    let mut score = post_residual as f64;

    // Progress fraction (0.0 at start, 1.0 at end)
    let progress = step_index as f64 / total_items as f64;

    // ---------- 1. 2‑step lookahead ----------
    if next_item_size > 0 {
        let diff = post_residual as i32 - next_item_size as i32;
        if diff >= 0 {
            // Can fit the next item – reward small gap
            score -= (diff.abs() as f64).powi(2) * 0.008;
            if diff < (next_item_size as i32 / 2) {
                score -= 2.0;
            }
        } else {
            // Cannot fit – heavy penalty
            score += (-diff as f64).powi(2) * 0.04;
        }
    }

    // ---------- 2. Residual vs mean ----------
    let mean_diff = (post_residual as f64 - mean_residual).abs();
    score += mean_diff * 0.08 * progress;

    // ---------- 3. Single‑fit bonus ----------
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // ---------- 4. New bin handling ----------
    if bin_residual == bin_capacity {
        let open_factor = if open_bins_count > 5 { 1.0 } else { 0.5 };
        let mean_factor = if mean_residual > (0.5 * bin_capacity as f64) { 1.0 } else { 0.5 };
        score += 4.0 * open_factor * mean_factor;
    }

    // ---------- 5. Open bin pressure ----------
    if open_bins_count > 8 {
        score += (open_bins_count as f64 - 8.0) * 0.03;
    } else {
        score += (open_bins_count as f64) * 0.04;
    }

    // ---------- 6. Dead space penalty ----------
    if post_residual < 4 {
        score += 8.0;
    } else if post_residual < 10 {
        score += 4.0;
    }

    // ---------- 7. Compaction factor ----------
    let comp = post_residual as f64 / bin_capacity as f64;
    if comp > 0.6 {
        score += (comp - 0.6) * 20.0;
    }

    // ---------- 8. Excess residual penalty ----------
    if post_residual as f64 > mean_residual + 0.1 * bin_capacity as f64 {
        score += 3.0;
    }

