pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Progress and remaining ratios
    let progress = step_index as f64 / total_items as f64;
    let remaining_ratio = 1.0 - progress;

    // Residual ratio after placement
    let post_ratio = post_residual as f64 / bin_capacity as f64;

    // Base score: tighter bins get lower scores
    let mut score = 45.0 * post_ratio;

    // Exact fit penalty
    if post_residual == 0 {
        score -= 10.0;
    }

    // Look‑ahead: anticipate next item
    if next_item_size > 0 {
        let diff = post_residual as i32 - next_item_size as i32;
        let size_factor = (next_item_size as f64 / bin_capacity as f64).sqrt();
        if diff >= 0 {
            // Next item fits – reward tightness
            score -= 0.05 * (diff as f64).powi(2) * size_factor;
            if diff < (next_item_size as i32 / 4) {
                score -= 6.0;
            }
        } else {
            // Next item does not fit – penalty
            score += 0.07 * (-diff as f64).powf(1.5) * (1.0 - size_factor);
        }
    }

    // Deviation from mean residual (encourage uniform packing)
    let mean_diff = (post_residual as f64 - mean_residual).abs();
    score += 0.10 * mean_diff * (1.0 - progress);

    // Orphan bin penalty
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New‑bin decision
    if bin_residual == bin_capacity {
        let open_factor = 1.0 + (open_bins_count as f64 / (total_items as f64 + 1.0));
        let mean_factor = if mean_residual > 0.25 * bin_capacity as f64 { 1.15 } else { 0.85 };
        score += 3.5 * open_factor * mean_factor;
    }

    // Pressure from number of open bins (logistic)
    let z = (open_bins_count as f64 - 5.0).exp();
    let pressure = 0.06 / (1.0 + (-z).exp());
    score += pressure;

    // Dead‑space penalty (smoother)
    let dead_penalty = 20.0 * (1.0 - (post_residual as f64 / 20.0).min(1.0));
    score += dead_penalty;

    // Compaction factor
    if post_ratio > 0.97 {
        score -= (post_ratio - 0.97) * 50.0;
    } else if post_ratio < 0.25 {
        score += (0.25 - post_ratio) * 35.0;
    }

    // Excess residual penalty
    if post_residual as f64 > mean_residual + 0.15 * bin_capacity as f64 {
        score += 3.0;
    }

    // Late‑stage tightening
    if remaining_ratio < 0.03 && post_ratio < 0.75 {
        score += (0.75 - post_ratio) * 30.0;
    }

    // Big‑item bonus
    if item_size > (0.9 * bin_capacity as f64) as u32 {
        score -= 10.0;
    }

    // Additional residual checks
    if post_residual > mean_residual + 0.4 * bin_residual
        && next_item_size < bin_residual / 3
    {
        score += 3.0;
    }
    if post_residual < mean_residual && bin_residual < (mean_residual / 2.0) as u32 {
        score -= 2.0;
    }

    // Future fit anticipation: penalize bins that will be too small for the next item
    if next_item_size > bin_residual
        && next_item_size <= bin_residual + 10
    {
        score += 5.0;
    }

    // Quadratic penalty for too many open bins
    score += 0.001 * (open_bins_count as f64).powi(2);

    score
}

