        score -= (post_ratio - 0.96) * 70.0;
    } else if post_ratio < 0.15 {
        score += (0.15 - post_ratio) * 55.0;
    }

    // Late‑stage tightening
    if remaining < 0.03 && post_ratio < 0.80 {
        score += (0.80 - post_ratio) * 35.0;
    }

    // Big‑item bonus
    if item_size > (0.9 * bin_capacity as f64) as u32 {
        score -= 20.0;
    }

    // Excess residual penalty
    if post_residual as f64 > mean_residual + 0.35 * bin_capacity as f64 {
        score += 3.0;
    }

    // Next‑item fit anticipation: penalise bins that will be too small
    if next_item_size > bin_residual && next_item_size <= bin_residual + 15 {
        score += 6.0;
    }

    // Quadratic penalty for too many open bins
    score += 0.0004 * (open_bins_count as f64).powi(2);

    // Ratio of fitting bins to open bins
    let fit_ratio = if open_bins_count > 0 {
        fitting_bins_count as f64 / open_bins_count as f64
    } else {
        0.0
    };
    if fit_ratio < 0.15 {
        score += 2.0;
    } else if fit_ratio > 0.80 {
        score -= 3.0;
    }

    // Gap penalty: moderate residuals are slightly rewarded
    if post_residual >= 8 && post_residual <= 18 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // --- Progress & ratio ----
    let progress = step_index as f64 / total_items as f64;
    let remaining = 1.0 - progress;
    let post_ratio = post_residual as f64 / bin_capacity as f64;
    let mean_ratio = mean_residual / bin_capacity as f64;

    // --- Base penalty: tighter residuals are better ----
    let mut score = 12.0 * (1.0 - post_ratio);

    // --- Exact fit reward ----
    if post_residual == 0 {
        score -= 28.0;
    }

    // --- Residual fitting ----
    let diff = post_residual as i32 - item_size as i32;
    let item_ratio = item_size as f64 / bin_capacity as f64;
    if diff >= 0 {
        // Good fit: mild quadratic penalty scaled by fit quality
        let fit_factor = 1.0 - item_ratio.sqrt();
        score += 0.02 * (diff as f64).powi(2) * fit_factor;

        // Small residual bonus
        if diff < (item_size as i32 / 20) {
            score -= 8.0;
        } else if diff < (item_size as i32 / 10) {
            score -= 4.0;
        }
    } else {
        // Insufficient space: heavier penalty
        let penalty = 0.05
            * (-diff as f64).powf(1.6)
            * (1.0 - item_ratio.sqrt());
        score += penalty;
    }

    // --- Look‑ahead: anticipate next item ----
    if next_item_size > 0 {
        let diff_next = post_residual as i32 - next_item_size as i32;
        let next_ratio = next_item_size as f64 / bin_capacity as f64;
        if diff_next >= 0 {
            // Next item would fit
            score -= 2.5;
            // Slight bonus if it would fit with very small leftover
            if diff_next < 5 {
                score -= 0.5;
            }
        } else {
            // Next item would overflow
            let penalty_next = 0.04
                * (-diff_next as f64).powf(1.4)
                * (1.0 - next_ratio.sqrt());
            score += penalty_next;
        }
    }

    // --- Mean residual deviation ----
    let mean_diff = (post_residual as f64 - mean_residual).abs();
    score += 0.03 * mean_diff * (1.0 - 0.4 * progress);

    // --- Orphan‑bin penalty ----
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // --- New‑bin decision ----
    if bin_residual == bin_capacity {
        let open_factor = 1.0
            + (open_bins_count as f64)
                / (total_items as f64 * 0.8 + 5.0);
        let mean_factor = if mean_residual > 0.25 * bin_capacity as f64 {
            1.1
        } else {
            0.8
        };
        score += 2.0 * open_factor * mean_factor;
        if remaining < 0.07 && open_bins_count > 6 {
            score += 1.5;
        }
    }

    // --- Logistic pressure based on open bins ----
    let z = ((open_bins_count as f64) - 4.0).exp();
    let pressure = 0.04 / (1.0 + (-z).exp());
    score += pressure;

    // --- Dead‑space penalty ----
    let dead_penalty = 4.0 * (1.0 - post_ratio.min(1.0));
    score += dead_penalty;

    // --- Compaction incentives ----
    if post_ratio > 0.97 {
        score -= (post_ratio - 0.97) * 140.0;
    } else if post_ratio < 0.10 {
        score += (0.10 - post_ratio) * 70.0;
    }

    // --- Late‑stage tightening ----
    if remaining < 0.02 && post_ratio < 0.65 {
        score += (0.65 - post_ratio) * 20.0;
    }

    // --- Big‑item bonus ----
    if item_size > (0.88 * bin_capacity as f64) as u32 {
        score -= 6.0;
    }

    // --- Excess residual penalty ----
    if post_residual as f64 > mean_residual + 0.25 * bin_capacity as f64 {
        score += 1.5;
    }

    // --- Next‑item fit anticipation ----
    if next_item_size > bin_residual && next_item_size <= bin_residual + 10 {
        score += 1.5;
    }

    // --- Residual‑ratio deviation penalty ----
    if post_ratio > mean_ratio + 0.10 {
        let excess = post_ratio - (mean_ratio + 0.10);
        score += 2.0 * excess;
    }

    // --- Quadratic open‑bins penalty ----
    score += 0.00012 * (open_bins_count as f64).powi(2);

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score: residual after placement
    let mut score = post_residual as f64;

    // Ratios
    let residual_ratio = post_residual as f64 / bin_capacity as f64;
    let pre_residual_ratio = bin_residual as f64 / bin_capacity as f64;
    let progress = step_index as f64 / total_items as f64;

    // New empty bin handling
    if bin_residual == bin_capacity {
        let mut penalty = bin_capacity as f64 * 0.6;
        if item_size as f64 > bin_capacity as f64 * 0.9 {
            penalty *= 0.3;
        }
        if open_bins_count <= 3 {
            penalty *= 1.3;
        } else if open_bins_count <= 6 {
            penalty *= 1.1;
        }
        // Early in stream penalise new bins more
        if progress < 0.2 {
            penalty *= 1.2;
        }
        score += penalty;

        // Bonuses for large items
        if item_size as f64 > bin_capacity as f64 * 0.8 {
            score -= 15.0;
        } else if item_size as f64 > bin_capacity as f64 * 0.7 {
            score -= 8.0;
        } else if item_size as f64 > bin_capacity as f64 * 0.6 {
            score -= 4.0;
        }
    }

    // Unused space penalty, stronger later
    score += residual_ratio * residual_ratio * 22.0 * (1.0 + progress * 0.5);

    // Prefer bins that were tight before placement
    if pre_residual_ratio < 0.15 {
        score -= 4.0;
    } else if pre_residual_ratio < 0.3 {
        score -= 2.0;
    }

    // Next‑item fit encouragement
    if next_item_size <= post_residual {
        score -= 12.0;
    } else {
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    // Slight penalty for high overall mean residual
    score += mean_residual * 0.08;

    // Discourage many open bins
    score += (open_bins_count as f64) * 0.04;
    if open_bins_count > 12 {
        score += 2.0;
    }

    // Tightening pressure as we progress
    score += (1.0 - progress) * 1.5;

    // Penalty for being far from the tightest fits
    score += (fitting_bins_count as f64) * 0.15;

    // Extra bonus for extremely tight fits
    if residual_ratio < 0.03 {
        score -= 8.0;
    } else if residual_ratio < 0.06 {
        score -= 4.0;
    }

    // Penalty if the next item will not fit after current placement
    if next_item_size > bin_residual - item_size {
        score += 3.5;
    }

    // Penalty for using a bin that is far larger than the average residual
    if bin_residual as f64 > mean_residual * 1.5 {
        score += (bin_residual as f64 - mean_residual * 1.5) * 0.02;
    }

    // Minor penalty if the residual is still large relative to capacity
    if residual_ratio > 0.5 {
        score += 0.5;
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Progress and remaining ratio
    let progress = step_index as f64 / total_items as f64;
    let remaining_ratio = 1.0 - progress;

    // Residual ratio after placing the item
    let post_ratio = post_residual as f64 / bin_capacity as f64;

    // Base score proportional to how full the bin is
    let mut score = 50.0 * post_ratio;

    // Exact fit penalty
    if post_residual == 0 {
        score -= 12.0;
    }

    // Look‑ahead reward/penalty
    if next_item_size > 0 {
        let diff = post_residual as i32 - next_item_size as i32;
        let size_factor = (next_item_size as f64 / bin_capacity as f64).sqrt();
        if diff >= 0 {
            // Next item fits – reward tightness
            score -= 0.04 * (diff as f64).powi(2) * size_factor;
            if diff < (next_item_size as i32 / 3) {
                score -= 4.0;
            }
        } else {
            // Next item does not fit – penalty
            score += 0.06 * (-diff as f64).powi(2) * (1.0 - size_factor);
        }
    }

    // Deviation from mean residual (encourage uniform packing)
    let mean_diff = (post_residual as f64 - mean_residual).abs();
    score += 0.12 * mean_diff * (1.0 - progress);

    // Orphan bin bonus (avoid single‑fit bins)
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New‑bin decision
    if bin_residual == bin_capacity {
        let open_factor = if open_bins_count > total_items / 10 {
            1.3
        } else {
            0.7
        };
        let mean_factor = if mean_residual > 0.3 * bin_capacity as f64 {
            1.2
        } else {
            0.8
        };
        score += 4.0 * open_factor * mean_factor;
    }

    // Pressure from the number of open bins (logistic curve)
    let x = open_bins_count as f64 - 8.0;
    let pressure = (x.exp() / (1.0 + x.exp())) * 0.05;
    score += pressure;

    // Dead‑space penalty
    if post_residual < 5 {
        score += 18.0;
    } else if post_residual < 12 {
        score += 9.0;
    } else if post_residual > 25 {
        score += 6.0;
    }

    // Compaction factor (reward tight bins, penalize very empty)
    if post_ratio > 0.95 {
        score -= (post_ratio - 0.95) * 40.0;
    } else if post_ratio < 0.30 {
        score += (0.30 - post_ratio) * 30.0;
    }

    // Excess residual penalty
    if post_residual as f64 > mean_residual + 0.2 * bin_capacity as f64 {
        score += 4.5;
    }

    // Late‑stage tightening
    if remaining_ratio < 0.04 && post_ratio < 0.80 {
        score += (0.80 - post_ratio) * 35.0;
    }

    // Big‑item bonus
    if item_size > (0.85 * bin_capacity as f64) as u32 {
        score -= 9.0;
    }

    // Additional residual checks
    if post_residual > mean_residual + 0.4 * bin_residual
        && next_item_size < bin_residual / 3
    {
        score += 3.0;
    }
    if post_residual < mean_residual && bin_residual < (mean_residual / 2.0) as u32 {
        score -= 2.0;
    }

    score
}
